from .cli import format_distance
from .data import PLACES


def search(query="", step_free=False, places=None):
    """Places whose name contains `query` (case-insensitive), optionally only step-free ones,
    sorted by distance, farthest first."""
    found = [p for p in (PLACES if places is None else places)
             if query.lower() in p["name"].lower() and (p["step_free"] or not step_free)]
    return sorted(found, key=lambda p: p["distance_m"], reverse=True)


def describe(place):
    return f"{place['name']} ({format_distance(place['distance_m'])})"

