import argparse
import json
import sys

from .search import describe, search


def format_distance(distance_m):
    if distance_m < 1000:
        return f"{distance_m} m"
    return f"{distance_m / 1000:.1f} km"


def format_count(n):
    if n == 1:
        return "1 place found"
    return f"{n} places found"


def main(argv=None):
    parser = argparse.ArgumentParser(prog="accessplaces")
    parser.add_argument("query", nargs="?", default="")
    parser.add_argument("--step-free", action="store_true", help="only places with step-free access")
    parser.add_argument("--json", action="store_true", help="print the result as JSON")
    parser.add_argument("--names-only", action="store_true", help="print only the place names")
    args = parser.parse_args(argv)
    found = search(args.query, args.step_free)
    if args.json:
        print(json.dumps(found))
    elif args.names_only:
        for place in found:
            print(place["name"])
    else:
        for place in found:
            print(describe(place))
        print(format_count(len(found)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
